{
  "name": "I²C主控制器",
  "name_en": "I2C Master Controller",
  "manufacturer": "",
  "description": "这是一种I²C总线主控接口模块，用于在实验系统中与各类I²C从设备进行通信。它通常用于向外设写入配置数据、读取寄存器或采集数字数据，适合实验平台中的传感器、存储器及其他低速数字器件联机控制与测试。",
  "description_en": "This is an I2C bus master interface module used to communicate with I2C slave devices in laboratory systems. It is typically used to write configuration data to peripherals, read registers, or acquire digital data, and is suitable for controlling and testing sensors, memory devices, and other low-speed digital components in experimental setups.",
  "tag_hints": [
    "I2C communication",
    "bus master controller",
    "register readout",
    "peripheral configuration",
    "digital instrumentation",
    "embedded lab hardware"
  ],
  "actions": [
    {
      "action_name": "auto-init",
      "description": "初始化I²C主控制器。",
      "description_en": "Initialize the I2C master controller."
    },
    {
      "action_name": "auto-reset",
      "description": "复位I²C主控制器。",
      "description_en": "Reset the I2C master controller."
    },
    {
      "action_name": "auto-start",
      "description": "启动一次I²C传输。",
      "description_en": "Start an I2C transfer."
    },
    {
      "action_name": "auto-set_addr",
      "description": "设置I²C从设备地址。",
      "description_en": "Set the I2C slave device address."
    },
    {
      "action_name": "auto-set_address",
      "description": "设置I²C从设备地址。",
      "description_en": "Set the I2C slave device address."
    },
    {
      "action_name": "auto-set_size",
      "description": "设置传输数据长度。",
      "description_en": "Set the transfer data length."
    },
    {
      "action_name": "auto-is_done",
      "description": "检查当前I²C传输是否完成。",
      "description_en": "Check whether the current I2C transfer is complete."
    },
    {
      "action_name": "auto-set_data",
      "description": "定义传输数据缓冲区。",
      "description_en": "Define the transfer data buffer."
    },
    {
      "action_name": "auto-write",
      "description": "向指定I²C从设备写入数据。",
      "description_en": "Write data to the specified I2C slave device."
    },
    {
      "action_name": "auto-read",
      "description": "从指定I²C从设备读取数据。",
      "description_en": "Read data from the specified I2C slave device."
    }
  ]
}

